// ViewModelLibrary.cs
//
// Which first-person models and clips belong to each weapon id. The asset is generated by
// Zombies > BYO > Build Viewmodel Library from the manifest tools/byo_weapons.py writes; it only
// references assets inside the project's (never shared) BYO folder.

using System;
using System.Collections.Generic;
using UnityEngine;

namespace ZombiesPort
{
    [CreateAssetMenu(menuName = "Zombies/Viewmodel Library")]
    public class ViewModelLibrary : ScriptableObject
    {
        [Serializable]
        public class ClipRef
        {
            public string key;      // weapon-file field, e.g. "fireAnim", "adsUpAnim"
            public TextAsset clip;
        }

        [Serializable]
        public class Entry
        {
            public string weaponId;
            public GameObject gunPrefab;
            public List<ClipRef> clips = new List<ClipRef>();
            public float adsFov = 65f;
            [Tooltip("Weapon-file hideTags: attachment bones whose geometry is hidden (suppressor, extended clip...).")]
            public List<string> hideTags = new List<string>();
            public List<string> soundKeys = new List<string>();
            public List<string> soundAliases = new List<string>();

            public TextAsset Clip(string key)
            {
                foreach (var c in clips) if (c.key == key) return c.clip;
                return null;
            }

            public string Sound(string key)
            {
                int i = soundKeys.IndexOf(key);
                return i >= 0 ? soundAliases[i] : null;
            }
        }

        public GameObject handsPrefab;
        public List<Entry> weapons = new List<Entry>();
        [Tooltip("Knife swing clip, used for every weapon (BO1 viewmodels share the knife melee).")]
        public TextAsset knifeClip;

        public Entry Find(string weaponId)
        {
            foreach (var e in weapons) if (e.weaponId == weaponId) return e;
            return null;
        }
    }
}
